    /**
     * Method to retrieve the Team via an TeamPrimaryKey.
     * @param 	id Long
     * @return 	Team
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Team handle( FindTeamQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTeamId() );
    }
    
    /**
     * Method to retrieve a collection of all Teams
     *
     * @param	query	FindAllTeamQuery 
     * @return 	List<Team> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Team> handle( FindAllTeamQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTeam,
 * but only if the id matches
 *
 * @param		entity	Team
 */
	protected void emitFindTeam( Team entity ) {
		LOGGER.info("handling emitFindTeam" );
		
	    queryUpdateEmitter.emit(FindTeamQuery.class,
	                            query -> query.getFilter().getTeamId().equals(entity.getTeamId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTeam
	 * 
	 * @param		entity	Team
	 */
	protected void emitFindAllTeam( Team entity ) {
		LOGGER.info("handling emitFindAllTeam" );
		
	    queryUpdateEmitter.emit(FindAllTeamQuery.class,
	                            query -> true,
	                            entity);
	}

